if mibBuilder.loadTexts: cd11IfDesiredSsidMaxAssocSta.setDescription("This object defines the maximum number of IEEE \n                802.11 stations which may associate with this radio \n                interface through IEEE802dot11-MIB dot11DesiredSSID.  \n                If this value is '0', the maximum number is limited\n                only by the IEEE 802.11 standard and any hardware or\n                radio firmware limitations of the access point.  The\n                default value is '0'.")
cd11IfAuxiliarySsidLength = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 272, 1, 1, 1, 1, 1, 8), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 4095))).setMaxAccess("readonly")
if mibBuilder.loadTexts: cd11IfAuxiliarySsidLength.setStatus('current')
if mibBuilder.loadTexts: cd11IfAuxiliarySsidLength.setDescription("This object specifies the maximum number of SSIDs\n                allowed for a radio interface or the number of SSID \n                entries per radio interface in the cd11IfAuxSsidTable.\n                The default value is '25'.")
