cd11IfDesiredSsidMicAlgorithm = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 272, 1, 1, 1, 1, 1, 10), CDot11IfMicAlgorithm()).setMaxAccess("readwrite")
