cd11IfDesiredSsidWepPermuteAlg = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 272, 1, 1, 1, 1, 1, 11), CDot11IfWepKeyPermuteAlgorithm()).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cd11IfDesiredSsidWepPermuteAlg.setReference('IEEE Std 802.11-Jan 14 1999, Wireless LAN Medium \n                Access Control and Physical Layer Specifications,\n                LAN MAN Standards Committee of the IEEE Computer \n                Society, section 8.2.3.')
