cd11IfAuthAlgDefaultVlan = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 272, 1, 1, 1, 2, 1, 3), CDot11IfVlanIdOrZero()).setMaxAccess("readwrite")
